```cpp
#include <ESP8266WiFi.h>
#include <RainbowLEDStrip.h>

const int buttonPin = 2; // Replace with the pin number of your button
int currentLed = 0;

RainbowLEDStrip ledStrip(60); // Assuming you have a 60 LED strip

void setup() {
  Serial.begin(115200);
  WiFi.begin("your_ssid", "your_password");
  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Connecting to WiFi...");
  }
  Serial.println("Connected to WiFi");
}

void loop() {
  if (digitalRead(buttonPin) == HIGH) {
    currentLed++;
    if (currentLed > 60) {
      currentLed = 0;
    }
    ledStrip.setColor(currentLed, Wheel(255));
    delay(500);
  }
}

uint32_t Wheel(byte pos) {
  if (pos < 85) {
    return ledStrip.color(pos * 3, 255 - pos * 3, pos * 3);
  } else if (pos < 170) {
    pos -= 85;
    return ledStrip.color(255 - pos * 3, pos * 3, pos * 3);
  } else {
    pos -= 170;
    return ledStrip.color(pos * 3, pos * 3, 255 - pos * 3);
  }
}
```

Replace "your_ssid" and "your_password" with your WiFi credentials. This code will light up the LED strip one by one when the button is pressed, and the color of each LED will fade with the rainbow colors.

