3. Control the relays using the `digitalWrite()` function:

```cpp
void loop() {
    // Turn on relay2
    digitalWrite(14, HIGH);
    delay(1000);
    // Turn off relay2
    digitalWrite(14, LOW);
    delay(1000);

    // Turn on relay1
    digitalWrite(12, HIGH);
    delay(1000);
    // Turn off relay1
    digitalWrite(12, LOW);
    delay(1000);

    // Turn on relay0
    digitalWrite(13, HIGH);
    delay(1000);
    // Turn off relay0
    digitalWrite(13, LOW);
    delay(1000);
}
