Here's a simple React Hooks component that converts temperatures between Celsius, Fahrenheit, and Kelvin:

```javascript
import React, { useState } from 'react';

function useTemperatureConverter() {
  const [temperature, setTemperature] = useState(0);
  const [unit, setUnit] = useState('celsius');

  function handleConvert(newUnit) {
    if (newUnit === 'celsius') {
      setTemperature((temperature * 9 / 5) + 32);
      setUnit('fahrenheit');
    } else if (newUnit === 'fahrenheit') {
      setTemperature((temperature - 32) * 5 / 9);
      setUnit('celsius');
    } else if (newUnit === 'kelvin') {
      setTemperature(temperature + 273.15);
      setUnit('kelvin');
    }
  }

  return { temperature, unit, handleConvert };
}

export default function TemperatureConverter() {
  const { temperature, unit, handleConvert } = useTemperatureConverter();

  return (
    <div>
      <h2>Temperature Converter</h2>
      <p>Temperature: {temperature} {unit}</p>
      <button onClick={() => handleConvert('fahrenheit')}>Convert to Fahrenheit</button>
      <button onClick={() => handleConvert('kelvin')}>Convert to Kelvin</button>
    </div>
  );
}
```

This component uses the `useState` hook to manage the current temperature value and the selected unit. The `handleConvert` function is called when the user clicks on the "Convert to Fahrenheit" or "Convert to Kelvin" button, which updates the temperature value and the selected unit accordingly.

