```csharp
using UnityEngine;
using UnityEngine.Audio;
using UnityEngine.UI;

public class MusicVisualizer : MonoBehaviour
{
    public AudioSource audioSource;
    public RectTransform visualizerRectTransform;
    public float visualizerWidth = 100f;
    public float visualizerHeight = 100f;
    public Color[] colors = { Color.red, Color.green, Color.blue, Color.yellow };

    private float[] spectrumData;

    void Start()
    {
        audioSource = GetComponent<AudioSource>();
        visualizerRectTransform = GetComponent<RectTransform>();

        spectrumData = new float[audioSource.clip.samples];
    }

    void Update()
    {
        int sampleIndex = (int)audioSource.timeSamples;
        audioSource.GetSpectrumData(spectrumData, 0, FFTWindow.Blackman);

        float maxValue = 0f;
        for (int i = 0; i < spectrumData.Length; i++)
        {
            maxValue = Mathf.Max(maxValue, spectrumData[i]);
        }

        float normalizedValue = spectrumData[sampleIndex] / maxValue;
        float visualizerPositionX = visualizerWidth * normalizedValue;
        float visualizerPositionY = visualizerHeight * (1f - normalizedValue);

        Vector2 visualizerPosition = new Vector2(visualizerPositionX, visualizerPositionY);
        visualizerRectTransform.anchoredPosition = visualizerPosition;
    }
}
```

