To create a simple toast notification using React Context, follow these steps:

1. Create a ToastContext.js file:

```javascript
import React, { createContext, useState } from 'react';

const ToastContext = createContext();

function ToastProvider({ children }) {
  const [toast, setToast] = useState(null);

  function showToast(message) {
    setToast(message);
    setTimeout(() => {
      setToast(null);
    }, 3000);
  }

  return (
    <ToastContext.Provider value={{ showToast }}>
      {children}
    </ToastContext.Provider>
  );
}

export { ToastContext, ToastProvider };
```

2. Import the ToastContext and ToastProvider in your main application file:

```javascript
import React from 'react';
import ToastContext from './ToastContext';
import ToastProvider from './ToastProvider';

function App() {
  return (
    <ToastProvider>
      {/* Your application content goes here */}
    </ToastProvider>
  );
}

export default App;
```

3. Use the ToastContext in your components to display toast notifications:

```javascript
import React from 'react';
import { useContext } from 'react';
import ToastContext from './ToastContext';

function MyComponent() {
  const { showToast } = useContext(ToastContext);

  function handleClick() {
    showToast('This is a toast notification!');
  }

  return (
    <div>
      <button onClick={handleClick}>Show Toast</button>
    </div>
  );
}

export default MyComponent;
```

Now you have a simple toast notification system using React Context. You can use the `showToast` function from the ToastContext to display toast notifications in your components.

Here's an example of how you can display the set of prime numbers and calculate their product using HTML, CSS, and JavaScript:

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Prime Numbers</title>
    <style>
        body {
            font-family: Arial, sans-serif;
        }

        h1 {
            text-align: center;
        }

        ul {
            list-style: none;
            padding: 0;
        }

        li {
            margin-bottom: 5px;
        }
    </style>
</head>
<body>
    <h1>Prime Numbers</h1>
    <ul>
        <li>3</li>
        <li>7</li>
        <li>13</li>
        <li>19</li>
    </ul>
    <script>
        function calculateProduct() {
            const primeNumbers = [3, 7, 13, 19];
            let product = 1;

            for (let i = 0; i < primeNumbers.length; i++) {
                product *= primeNumbers[i];
            }

            return product;
        }

        const productElement = document.createElement('p');
        productElement.textContent = `The product of the prime numbers is ${calculateProduct()}.`;
        document.body.appendChild(productElement);
    </script>
</body>
</html>
```

This code creates an unordered list (`<ul>`) containing the prime numbers (3, 7, 13, and 19). It then uses JavaScript to calculate the product of these numbers and displays the result as a paragraph element (`<p>`) at the bottom of the page.

