def _convert_to_words(num):
    words = []
    while num >= 1000:
        hundreds = num // 1000
        remainder = num % 1000
        words.append(str(hundreds) + " thousand")
        num -= hundreds * 1000
    while num >= 100:
        hundreds = num // 100
        remainder = num % 100
        words.append(str(hundreds) + " hundred")
        num -= hundreds * 100
    while num >= 10:
        tens = num // 10
        remainder = num % 10
        words.append(str(tens) + " " + str(remainder))
        num -= tens * 10
    words.append(str(num))
    return " ".join(reversed(words))

