```typescript
import { useCombobox } from 'downshift';
import axios from 'axios';

const EmailInput = () => {
  const [searchTerm, setSearchTerm] = React.useState('');
  const [emails, setEmails] = React.useState([]);

  const { isOpen, selectedItem, getMenuProps, getInputProps } = useCombobox({
    items: emails,
    onSelect: (item) => setSelectedItem(item),
  });

  const handleInputChange = (event) => {
    setSearchTerm(event.target.value);
    searchEmails(event.target.value);
  };

  const searchEmails = async (prefix) => {
    try {
      const response = await axios.get(`https://api.example.com/emails`, {
        params: { prefix },
      });
      setEmails(response.data);
    } catch (error) {
      console.error(error);
    }
  };

  return (
    <div {...getMenuProps()}>
      <input
        type="text"
        {...getInputProps({
          placeholder: 'Search emails',
          value: searchTerm,
          onChange: handleInputChange,
        })}
      />
      {isOpen && (
        <ul {...getMenuProps()}>
          {emails.map((email) => (
            <li key={email.id} {...getMenuItemProps({ item: email })}>
              {email.name} - {email.email}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default EmailInput;
```

