// Import necessary modules
import React, { useState } from 'react';
import Chart from 'chart.js';

interface Dataset {
  label: string;
  data: number[];
}

const BarChart: React.FC = () => {
  const [dataset, setDataset] = useState<Dataset[]>([]);

  const handleAddData = () => {
    const newDataset: Dataset = {
      label: `New Dataset ${dataset.length + 1}`,
      data: Array(10).fill(Math.random() * 100),
    };
    setDataset([...dataset, newDataset]);
  };

  const handleRemoveData = (index: number) => {
    setDataset(dataset.filter((_, i) => i !== index));
  };

  const handleUpdateData = (index: number, newData: number[]) => {
    setDataset(dataset.map((dataset, i) => (i === index ? { ...dataset, data: newData } : dataset)));
  };

  const options: Chart.Options = {
    scales: {
      y: {
        beginAtZero: true,
      },
    },
  };

  return (
    <div>
      <button onClick={handleAddData}>Add Data</button>
      <button onClick={() => handleRemoveData(dataset.length - 1)}>Remove Last Data</button>
      <button onClick={() => handleUpdateData(dataset.length - 1, Array(10).fill(Math.random() * 100))}>Update Last Data</button>
      <div id="bar-chart"></div>
    </div>
  );
};

export default BarChart;
```

