#include <iostream>
#include <curl/curl.h>
#include <json/json.h>

using namespace std;

string getFacebookData(string accessToken) {
    CURL *curl;
    CURLcode res;
    string readBuffer;

    curl = curl_easy_init();
    if (curl) {
        string url = "https://graph.facebook.com/me?access_token=" + accessToken;
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK)
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));

        curl_easy_cleanup(curl);
    }

    Json::Value root;
    Json::Reader reader;

    if (reader.parse(readBuffer, root)) {
        return root["name"].asString();
    } else {
        return "";
    }
}

int main() {
    string accessToken = "YOUR_FACEBOOK_ACCESS_TOKEN";
    string name = getFacebookData(accessToken);

    cout << "Name: " << name << endl;

    return 0;
}
```

